const preset={'aura-undies':['clothing'],'aura-expressions':['objects'],'drinks':['drinks'],'p4a':['collections'],'gajra':['collections'],'hygiene':['hygiene'],'purple-mat':['mat'],'sandy-club':['collections','gatherings'],'joy-gathering':['gatherings','drinks']};
function direction(fields={},caseKey=''){
 if(Object.hasOwn(profiles,fields.ideasFocus))return [fields.ideasFocus];
 // A specific product name takes priority over the broad examples in a preset.
 const matches=text=>Object.keys(profiles).filter(k=>profiles[k].match.test(text||''));
 let found=matches(fields.name);
 if(!found.length)found=matches(fields.intention);
 if(!found.length)found=preset[caseKey]||matches(fields.specification);
 if(found.includes('mat'))found=found.filter(k=>k!=='hygiene'&&k!=='collections');
 return found;
}
function suggest(fields={},caseKey='',tab='brief'){
 const groups=direction(fields,caseKey);
 const lists=groups.map(k=>profiles[k][tab]||[]);
 // Interleave relevant families so a mixed idea keeps both contributions visible.
 let items=[];for(let n=0;n<Math.max(0,...lists.map(l=>l.length));n++)for(const list of lists)if(list[n])items.push(list[n]);
 items.push(...(common[tab]||[]));
 if(tab==='handoff'&&groups.length){const names=groups.map(k=>profiles[k].label).join(' and ');items.unshift(idea('agentTask','Develop this product’s next step',`Prepare a draft next-step plan for this ${names} idea using the current brief, sample notes and connected contributions. Keep unknowns visible for review.`));}
 const seen=new Set();items=items.filter(item=>{const key=item.field+'|'+item.text;if(seen.has(key))return false;seen.add(key);return true;});
 return {groups,labels:groups.map(k=>profiles[k].label),items};
}
function append(current,text){const value=String(current||'');if(value.includes(text))return value;return value.trim()?value+'\n\n'+text:text;}
return {suggest,direction,append,profiles};
